/* Smooth time-off editor; availability is saved to the existing calendar block model. */
function blockClock(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function blockLabel(n){return `${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n>=720?'PM':'AM'}`;}
function blockDraft(){if(!state.blockDraft)state.blockDraft={mode:'time',from:state.calendarDate>=today?state.calendarDate:today,through:state.calendarDate>=today?state.calendarDate:today,start:720,end:780,reason:'Lunch break',barber:activeBarberId()};if(state.role==='Barber Pro')state.blockDraft.barber=activeBarberId();return state.blockDraft;}
function blockCandidates(d){if(!['full','time'].includes(d.mode)||!/^\d{4}-\d{2}-\d{2}$/.test(d.from)||iso(dateObj(d.from))!==d.from||d.from<today)throw Error('Choose today or a future date.');const through=d.mode==='full'?d.through:d.from;if(!/^\d{4}-\d{2}-\d{2}$/.test(through)||iso(dateObj(through))!==through||through<d.from)throw Error('The end date must be on or after the start date.');if(!barbers.some(b=>b.id===d.barber)||state.role==='Barber Pro'&&d.barber!==activeBarberId())throw Error('Choose a valid barber.');if(!d.reason.trim())throw Error('Add a short reason for this block.');if(d.mode==='time'&&(!Number.isInteger(d.start)||!Number.isInteger(d.end)||d.start%15||d.end%15||d.start<360||d.end>1320||d.end<=d.start))throw Error('Choose a valid time in 15-minute steps.');const dates=[];for(let date=d.from;date<=through;date=addDays(date,1)){if(dates.length===31)throw Error('Choose up to 31 days at a time.');dates.push(date);}const start=d.mode==='full'?0:d.start,end=d.mode==='full'?1439:d.end;if(dates.some(date=>bookings.some(b=>b.barber===d.barber&&b.date===date&&b.status!=='cancelled'&&minutes(b.time)<end&&minutes(b.time)+bookingDuration(b)>start)))throw Error('An appointment overlaps this block. Choose another time or reschedule the visit first.');if(dates.some(date=>extras.blocks.some(b=>b.barber===d.barber&&b.date===date&&clockMinutes(b.start)<end&&clockMinutes(b.end)>start)))throw Error('Some of this time is already blocked. Remove or adjust the existing block first.');return dates.map(date=>({id:'block-'+crypto.randomUUID(),barber:d.barber,date,start:d.mode==='full'?'00:00':blockClock(start),end:d.mode==='full'?'23:59':blockClock(end),reason:d.reason.trim().slice(0,80)}));}
function smoothBlockPage(){if(!isStaff())return head('Staff access required.','');const d=blockDraft(),blocks=extras.blocks.filter(b=>b.barber===d.barber&&b.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||clockMinutes(a.start)-clockMinutes(b.start));return `${head('Block time.','A break, a personal appointment or a day off.')}<form id="smooth-block-form" class="panel block-editor"><fieldset class="block-type"><legend>What would you like to block?</legend>${[['full','calendar','Full day','One day or a few days away'],['time','clock','Time block','A little space in your day']].map(([id,type,label,sub])=>`<label class="${d.mode===id?'selected':''}"><input type="radio" name="blockMode" value="${id}" ${d.mode===id?'checked':''}>${icon(type)}<span><strong>${label}</strong><small>${sub}</small></span></label>`).join('')}</fieldset>${state.role==='Owner HQ'?`<label class="field">Whose calendar?<select name="barber">${barbers.map(b=>`<option value="${b.id}" ${b.id===d.barber?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>`:''}<div class="block-date-fields"><label class="field">${d.mode==='full'?'First day':'Date'}<input type="date" name="from" min="${today}" value="${d.from}" required></label>${d.mode==='full'?`<label class="field">Last day<input type="date" name="through" min="${d.from}" value="${d.through}" required></label>`:''}</div><div class="block-date-chips" aria-label="Quick date selection">${Array.from({length:5},(_,i)=>{const date=addDays(today,i);return `<button type="button" data-block="date" data-block-date="${date}" class="${date===d.from?'selected':''}"><span>${i===0?'Today':i===1?'Tomorrow':pretty(date,{weekday:'short'})}</span><strong>${dateObj(date).getDate()}</strong></button>`;}).join('')}</div>${d.mode==='time'?`<section class="block-time-picker"><div class="block-time-summary" aria-live="polite"><strong id="block-time-label">${blockLabel(d.start)} – ${blockLabel(d.end)}</strong><span id="block-duration">${d.end-d.start} minutes</span></div><div class="block-window" aria-hidden="true"><span id="block-window-fill" style="left:${(d.start-360)/960*100}%;width:${(d.end-d.start)/960*100}%"></span></div>${[['start','Starts at',d.start],['end','Ends at',d.end]].map(([key,label,value])=>`<label class="block-slider"><span>${label}<output id="block-${key}-label" for="block-${key}">${blockLabel(value)}</output></span><input id="block-${key}" type="range" name="${key}" min="360" max="1320" step="15" value="${value}" aria-valuetext="${blockLabel(value)}"></label>`).join('')}<div class="block-duration-presets" role="group" aria-label="Block duration">${[15,30,60,120].map(n=>`<button type="button" data-block="duration" data-minutes="${n}" class="${d.end-d.start===n?'selected':''}">${n<60?n+' min':n/60+' hour'+(n>60?'s':'')}</button>`).join('')}</div><p class="block-quiet-note">Slide to adjust · 15-minute steps</p></section>`:`<div class="block-full-day">${icon('calendar')}<div><strong>No bookings. Just breathing room.</strong><p>The entire day is unavailable on your calendar.</p></div></div>`}<label class="field block-reason">Label for your calendar<input name="reason" maxlength="80" value="${esc(d.reason)}" required placeholder="e.g. Lunch break"></label><div class="block-reason-presets">${['Lunch break','Personal appointment','Time off'].map(reason=>`<button type="button" data-block="reason" data-reason="${reason}">${reason}</button>`).join('')}</div><p class="connect-error" role="alert" id="smooth-block-error"></p><button class="btn full" type="submit">${icon('check')} ${d.mode==='full'?'Block full day'+(d.through>d.from?'s':''):'Block this time'}</button><p class="block-quiet-note">Existing appointments stay protected. Remove a block any time.</p></form><section class="panel block-upcoming"><div class="row between"><h2>Your blocked time</h2><span class="muted">${blocks.length} block${blocks.length===1?'':'s'}</span></div>${blocks.length?blocks.slice(0,state.showAllBlocks?blocks.length:5).map(b=>`<div class="block-saved-row"><span class="block-date-tile"><strong>${dateObj(b.date).getDate()}</strong><small>${pretty(b.date,{month:'short'})}</small></span><span class="details"><strong>${esc(b.reason)}</strong><small>${pretty(b.date,{weekday:'short'})} · ${b.start==='00:00'&&b.end==='23:59'?'Full day':blockLabel(clockMinutes(b.start))+' – '+blockLabel(clockMinutes(b.end))}</small></span><button class="icon-btn" type="button" data-block="remove" data-id="${esc(b.id)}" aria-label="Remove ${esc(b.reason)} on ${pretty(b.date)}">${icon('close')}</button></div>`).join(''):'<p class="muted">A clear calendar. Your saved blocks will appear here.</p>'}${blocks.length>5?`<button class="text-btn" data-block="all">${state.showAllBlocks?'Show less':'View all blocked time'} ${icon('chevron')}</button>`:''}</section>`;}
const availabilityBeforeSmooth=availability;availability=function(){return isStaff()?smoothBlockPage():availabilityBeforeSmooth();};
function updateBlockSliders(changed){const d=blockDraft();if(changed==='start'&&d.start>=d.end)d.end=Math.min(1320,d.start+15);if(changed==='end'&&d.end<=d.start)d.start=Math.max(360,d.end-15);d.start=Math.max(360,Math.min(1305,d.start));d.end=Math.max(d.start+15,Math.min(1320,d.end));for(const key of ['start','end']){const range=document.querySelector('#block-'+key),label=document.querySelector('#block-'+key+'-label');if(range){range.value=d[key];range.setAttribute('aria-valuetext',blockLabel(d[key]));}if(label)label.textContent=blockLabel(d[key]);}const label=document.querySelector('#block-time-label'),duration=document.querySelector('#block-duration'),fill=document.querySelector('#block-window-fill');if(label)label.textContent=blockLabel(d.start)+' – '+blockLabel(d.end);if(duration)duration.textContent=(d.end-d.start)+' minutes';if(fill){fill.style.left=(d.start-360)/960*100+'%';fill.style.width=(d.end-d.start)/960*100+'%';}document.querySelectorAll('[data-block=duration]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.minutes)===d.end-d.start));}
document.addEventListener('input',e=>{if(!e.target.closest('#smooth-block-form'))return;const d=blockDraft(),input=e.target;if(['start','end'].includes(input.name)){d[input.name]=Number(input.value);updateBlockSliders(input.name);}else if(['from','through','reason'].includes(input.name)){d[input.name]=input.value;if(input.name==='from'){if(d.through<d.from)d.through=d.from;const through=document.querySelector('[name=through]');if(through){through.min=d.from;through.value=d.through;}document.querySelectorAll('[data-block=date]').forEach(b=>b.classList.toggle('selected',b.dataset.blockDate===d.from));}if(d.mode==='full'){const submit=document.querySelector('#smooth-block-form button[type=submit]');if(submit)submit.innerHTML=icon('check')+' Block full day'+(d.through>d.from?'s':'');}}});
document.addEventListener('change',e=>{if(!e.target.closest('#smooth-block-form'))return;const d=blockDraft();if(e.target.name==='blockMode'){d.mode=e.target.value;if(d.mode==='full'&&d.reason==='Lunch break')d.reason='Time off';render();}if(e.target.name==='barber'){d.barber=e.target.value;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-block]');if(!b||!isStaff())return;const d=blockDraft();if(b.dataset.block==='date'){d.from=b.dataset.blockDate;if(d.through<d.from||d.mode==='time')d.through=d.from;render();}if(b.dataset.block==='duration'){const n=Number(b.dataset.minutes);d.start=Math.min(d.start,1320-n);d.end=d.start+n;updateBlockSliders('end');}if(b.dataset.block==='reason'){d.reason=b.dataset.reason;const input=document.querySelector('#smooth-block-form [name=reason]');if(input)input.value=d.reason;}if(b.dataset.block==='remove'){const block=extras.blocks.find(x=>x.id===b.dataset.id);if(!block||block.barber!==d.barber)return;extras.blocks=extras.blocks.filter(x=>x.id!==block.id);save();render();toast('Time unblocked.');}if(b.dataset.block==='all'){state.showAllBlocks=!state.showAllBlocks;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='smooth-block-form')return;e.preventDefault();if(!isStaff())return;try{const d=blockDraft(),blocks=blockCandidates(d);extras.blocks.push(...blocks);save();state.calendarDate=d.from;state.agendaMonth=d.from.slice(0,7);state.blockDraft=null;go(state.role==='Owner HQ'?'calendar':'pCalendar');toast(blocks.length>1?'Days blocked. Your calendar is updated.':'Time blocked. Your calendar is updated.');}catch(err){document.querySelector('#smooth-block-error').textContent=err.message;}});
const renderBeforeSmoothBlock=render;render=function(){renderBeforeSmoothBlock();if(state.role==='Owner HQ'&&state.view==='calendar')document.querySelector('.page-head')?.insertAdjacentHTML('afterend',`<div class="block-owner-action"><button class="btn secondary" data-view="pBlock">${icon('clock')} Block time</button></div>`);};
render();
